+// Sales from the till. Each sale line is one dish sold `qty` times; it uses
+// one recipe portion per dish and consumes the ingredients with ledger ref
+// "sale:<ticket>". The ingredient quantities used are kept on the sale, so
+// the variance report compares them with what the ledger says was consumed.
+import { consume } from "./batches.js";
+import { listItems } from "./items.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** Tickets that have been imported already. */
+export function saleTickets(store) {
+  return new Set((store.data.sales ?? []).map((s) => s.ticket));
+}
+
+/** Records one sale line and consumes its ingredients (`uses`: [{ itemId, qty }]). */
+export function recordSale(store, { ticket, soldAt, dishId, qty, uses }) {
+  for (const u of uses) consume(store, u.itemId, u.qty, { at: soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  const sale = { id: store.nextId("sale"), ticket, soldAt, dishId, qty, uses };
+  store.data.sales.push(sale);
+  return sale;
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold in those days, actual use from every consume movement in them.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = instant.slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const u of s.uses) theoretical.set(u.itemId, round3((theoretical.get(u.itemId) ?? 0) + u.qty));
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, round3((actual.get(batch.itemId) ?? 0) + m.qty));
+  }
+  return listItems(store)
+    .map((item) => {
+      const t = theoretical.get(item.id) ?? 0;
+      const a = actual.get(item.id) ?? 0;
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
